// Помощники для тестов подарков (#75332d #ecc349 #9a50b0 #9d9088). Тексты — со скринов r10 12.11.2026 (веб 390 + iOS build 8).
// Селекторы экрана «שליחת מתנה» и строки «המתנות שקיבלתי» на живой странице ещё не проверялись — проверить при первом /qa-regress.
import { expect, type Page } from '@playwright/test';

export const N2 = 'QA П2 0011'; // new02, м
export const N10 = 'בדיקה כללי'; // new10, ж (в превью «בדיקה כללי שלחה לך מתנה»)

export async function phone(page: Page, width = 390, height = 844) {
  await page.setViewportSize({ width, height });
}

// /matches → строка партнёра → чат открыт (поле «כתוב הודעה»).
export async function openChat(page: Page, partner: string) {
  await page.goto('/matches');
  await page.getByText(partner, { exact: true }).last().click();
  await page.waitForURL(/\/chat\//);
  await expect(page.getByRole('textbox', { name: 'כתוב הודעה' })).toBeVisible();
}

// /settings → «המתנות שקיבלתי»; дождаться либо строк, либо пустого состояния.
export async function openReceivedGifts(page: Page) {
  await page.goto('/settings');
  await page.getByText('המתנות שקיבלתי', { exact: true }).first().click();
  await expect(page.getByText('המתנות שקיבלתי', { exact: true }).first()).toBeVisible();
  await expect(page.getByText('ורד זהב').first().or(page.getByText('עוד לא קיבלת מתנות'))).toBeVisible({ timeout: 20_000 });
}

// Строки списка от отправителя: элемент, внутри которого и имя, и «ורד זהב».
export function receivedRows(page: Page, sender: string) {
  return page.getByRole('button').filter({ hasText: sender }).filter({ hasText: 'ורד זהב' });
}

// В чате: 🎁 → экран «שליחת מתנה».
export async function openGiftSheet(page: Page) {
  await page.getByRole('button', { name: /מתנה|🎁|gift/i }).first().click();
  await expect(page.getByText('שליחת מתנה', { exact: true }).first()).toBeVisible();
}

// Поле сообщения к подарку (N/140) — не поле чата «כתוב הודעה».
export function giftMessageField(page: Page) {
  return page.getByRole('textbox').and(page.locator(':not([aria-label="כתוב הודעה"]):not([placeholder="כתוב הודעה"])')).last();
}

export const freeSendButton = (page: Page) => page.getByRole('button', { name: /שליחת מתנה.*חינם/ });
export const awaitingReplyHint = (page: Page, name: string) => page.getByText(new RegExp(`אפשר לשלוח עוד אחרי ש\\s?${name} (יענה|תענה)`));

// Закрыть экран «שליחת מתנה» (стрелка «חזרה» в шапке экрана) — вернуться в чат.
export async function closeGiftSheet(page: Page) {
  await page.getByRole('button', { name: /חזרה|סגירה|back|close/i }).first().click();
  await expect(page.getByRole('textbox', { name: 'כתוב הודעה' })).toBeVisible();
}

// Снять блок партнёра в /blocked-users (как в chat-personal, r9: окно «לבטל את החסימה של …?»).
export async function unblock(p: Page, name: string) {
  await p.goto('/blocked-users');
  await expect(p.getByText('משתמשים חסומים').first()).toBeVisible();
  const unblockBtn = p.getByRole('button', { name: `ביטול חסימה ${name}` });
  await expect(unblockBtn.or(p.getByText('אין משתמשים חסומים'))).toBeVisible();
  if (!(await unblockBtn.count())) return;
  const w = p.waitForResponse((r) => /block/i.test(r.url()) && !['GET', 'HEAD', 'OPTIONS'].includes(r.request().method()));
  await unblockBtn.click();
  const dlg = p.getByRole('dialog');
  const first = await Promise.race([w.then(() => 'sent' as const), dlg.waitFor().then(() => 'dialog' as const)]);
  if (first === 'dialog') {
    await expect(dlg.getByText(`לבטל את החסימה של ${name}?`)).toBeVisible();
    await dlg.getByRole('button', { name: 'לבטל חסימה', exact: true }).click();
  }
  expect((await w).ok(), 'запрос снятия блока 2xx').toBeTruthy();
  await expect(p.getByRole('button', { name: `ביטול חסימה ${name}` })).toHaveCount(0);
}

// ── Раунд 10, вторая партия (#802740 #64bad0 #ae03b1 #f676fe #f023a0). Тексты — со скринов r10; на живой странице не проверены.
export const FREE = 'QA חופשי'; // free
export const U4 = 'QA רביעית'; // user4

// В чате: 🎁 → (лист магазина «מתנה ל…» → «ורד זהב») → экран «שליחת מתנה» с кнопкой отправки.
export async function openSendScreen(page: Page, recipient: string) {
  await page.getByRole('button', { name: /מתנה|🎁|gift/i }).first().click();
  const store = page.getByText(new RegExp(`מתנה ל־?\\s?${recipient}`)).first();
  const send = page.getByRole('button', { name: /שליחת מתנה|המתנה נשלחה/ });
  await expect(store.or(send).first()).toBeVisible({ timeout: 20_000 });
  if (!(await send.first().isVisible())) {
    await page.getByText('ורד זהב', { exact: true }).first().click();
  }
  await expect(page.getByText('שליחת מתנה', { exact: true }).first()).toBeVisible();
}

// Есть ли на экране метка бесплатного подарка («חינם») — у отправителя с грантом.
export const hasFreeLabel = (page: Page) => page.getByText(/חינם/).first();

// /settings → «התראות» → переключатель по названию (role=switch, иначе строка с текстом).
export async function openNotificationSettings(page: Page) {
  await page.goto('/settings');
  await page.getByText('התראות', { exact: true }).first().click();
  await expect(page.getByText('מתנות ורצף').first()).toBeVisible({ timeout: 20_000 });
}
export function settingSwitch(page: Page, label: string) {
  return page.getByRole('switch', { name: new RegExp(label) }).or(
    page.locator('[role="switch"]').filter({ has: page.getByText(label) }),
  ).first();
}
export async function switchState(sw: import('@playwright/test').Locator): Promise<boolean> {
  return (await sw.getAttribute('aria-checked')) === 'true';
}
// Переключить и дождаться записи 2xx.
export async function setSwitch(page: Page, label: string, on: boolean) {
  const sw = settingSwitch(page, label);
  await expect(sw).toBeVisible();
  if ((await switchState(sw)) === on) return;
  const w = page.waitForResponse((r) => r.url().includes('/rest/v1/') && !['GET', 'HEAD', 'OPTIONS'].includes(r.request().method()));
  await sw.click();
  expect((await w).ok(), `сохранение «${label}» 2xx`).toBeTruthy();
  await expect(sw).toHaveAttribute('aria-checked', String(on));
}
